// NGINX upstream proxy configuration:
// upstream backend_nodes { server 127.0.0.1:3000; server 127.0.0.1:3001; }
// location / { proxy_pass http://backend_nodes; proxy_set_header X-Forwarded-For $remote_addr; }

import CircuitBreaker from 'opossum';
const breaker = new CircuitBreaker(fetchPaymentService, {
  timeout: 3000,
  errorThresholdPercentage: 50,
  resetTimeout: 10000
});
breaker.fallback(() => ({ status: 'unavailable', cached: true }));

